package main

import "fmt"

// Index는 comparable 인터페이스를 만족하는 모든 타입 슬라이스에서 x의 위치를 찾습니다.
func Index[T comparable](s []T, x T) int {
	for i, v := range s {
		if v == x {
			return i
		}
	}
	return -1
}

func main() {
	si := []int{10, 20, 15, -10}
	fmt.Println("20의 인덱스:", Index(si, 20))

	ss := []string{"apple", "banana", "cherry"}
	fmt.Println("banana의 인덱스:", Index(ss, "banana"))
}
